# --- bisect ------------------------------------------------------------------------------------------------


@st.composite
def bisect_cases(draw: st.DrawFn) -> tuple[int, int, frozenset[int]]:
    """A candidate count, the index of the true first bad candidate (size = only the `bad` ref) and skips."""
    size = draw(st.integers(min_value=1, max_value=300))
    first_bad = draw(st.integers(min_value=0, max_value=size))
    skips = draw(st.frozensets(st.integers(min_value=0, max_value=size - 1), max_size=size))
    return size, first_bad, skips


def oracle(index: int, first_bad: int, skips: frozenset[int]) -> Verdict:
    if index in skips:
        return Verdict.SKIP
    return Verdict.BAD if index >= first_bad else Verdict.GOOD


def run_search(size: int, first_bad: int, skips: frozenset[int]) -> tuple[Search, list[int]]:
    """Drive a search with an oracle that is right about every candidate it does not skip."""
    search = Search(size=size)
    tested: list[int] = []
    while (index := search.next_index()) is not None:
        tested.append(index)
        search.record(index, oracle(index, first_bad, skips))
        assert len(tested) <= size, "the search must end"
    return search, tested


@given(bisect_cases())
def test_bisect_isolates_the_first_bad_candidate(case: tuple[int, int, frozenset[int]]) -> None:
    size, first_bad, skips = case
    search, tested = run_search(size, first_bad, skips)
    result = search.result()

    assert len(tested) == len(set(tested)), "no candidate is tested twice"
    # the true first bad is the reported one, or hides among the skipped candidates right before it
    reported = result.first_bad if result.first_bad is not None else size
    assert first_bad == reported or first_bad in result.ambiguous
    assert all(i in skips for i in result.ambiguous)
    if not skips:
        assert result.first_bad == (first_bad if first_bad < size else None)
        assert result.ambiguous == []


@given(st.integers(min_value=1, max_value=10_000), st.data())
def test_bisect_without_skips_is_logarithmic(size: int, data: st.DataObject) -> None:
    first_bad = data.draw(st.integers(min_value=0, max_value=size))
    _, tested = run_search(size, first_bad, frozenset())
    assert len(tested) <= size.bit_length()


@given(st.integers(min_value=0, max_value=127))
def test_verdict_follows_git_bisect_run_exit_codes(code: int) -> None:
    expected = {0: Verdict.GOOD, 125: Verdict.SKIP}.get(code, Verdict.BAD)
    assert Verdict.from_exit_code(code) is expected


# --- ports -------------------------------------------------------------------------------------------------

PORT_BASE = 20_000
MAX_SLOTS = 8


@given(
    used=st.frozensets(st.integers(min_value=0, max_value=MAX_SLOTS - 1)),
    busy=st.frozensets(st.integers(min_value=PORT_BASE, max_value=PORT_BASE + BLOCK_SIZE * MAX_SLOTS - 1)),
)
def test_free_slot_is_the_lowest_usable_one(used: frozenset[int], busy: frozenset[int]) -> None:
    def free(port: int) -> bool:
        return port not in busy

    def usable(slot: int) -> bool:
        return slot not in used and all(free(p) for p in PortBlock.for_slot(PORT_BASE, slot).all_ports().values())

    slot = find_free_slot(used, port_base=PORT_BASE, max_slots=MAX_SLOTS, prober=free)
    if slot is None:
        assert not any(usable(s) for s in range(MAX_SLOTS))
    else:
        assert usable(slot)
        assert not any(usable(s) for s in range(slot))


@given(st.integers(min_value=1024, max_value=40_000), st.lists(st.integers(0, 50), min_size=2, max_size=5, unique=True))
def test_port_blocks_of_different_slots_never_overlap(base: int, slots: list[int]) -> None:
    assert max(PORT_OFFSETS.values()) < BLOCK_SIZE
    blocks = [set(PortBlock.for_slot(base, s).all_ports().values()) for s in slots]
    for i, a in enumerate(blocks):
        for b in blocks[i + 1 :]:
            assert not a & b


# --- spec --------------------------------------------------------------------------------------------------

# a value as people write it after `kind:`: no surrounding blanks, any other text including `:` or `/`
values = st.text(st.characters(blacklist_categories=("Cs", "Cc")), min_size=1, max_size=40).filter(
    lambda s: s == s.strip()
)


@pytest.mark.parametrize("cls", [ReleaseSource, GitSource, ArtifactSource, DockerSource])
@given(value=values)
def test_version_shorthand_round_trips(
    cls: type[ReleaseSource | GitSource | ArtifactSource | DockerSource], value: str
) -> None:
    kind = cls.model_fields["kind"].default
    source = cls.model_validate(parse_version_source(f"{kind}:{value}"))
    assert str(source) == f"{kind}:{value}"
    assert cls.model_validate(parse_version_source(str(source))) == source


def test_host_shorthand_round_trips() -> None:
    assert str(HostSource.model_validate(parse_version_source("host"))) == "host"


@given(st.text(max_size=30))
def test_unknown_or_malformed_shorthand_is_rejected(value: str) -> None:
    kind, sep, rest = value.partition(":")
    well_formed = (kind == "host" and not sep) or (
        kind in {"release", "git", "worktree", "artifact", "build", "docker"} and bool(rest)
    )
    assume(not well_formed)
    with pytest.raises(ValueError, match="version source"):
        parse_version_source(value)


# --- paths and strings -------------------------------------------------------------------------------------

segments = st.text(st.sampled_from("abcxyz0123-_"), min_size=1, max_size=6)
abs_paths = st.lists(segments, min_size=1, max_size=5).map(lambda parts: Path("/qft-hypothesis", *parts))


@given(st.lists(abs_paths, min_size=1, max_size=12))
def test_mount_roots_cover_every_path_once(paths: list[Path]) -> None:
    roots = mount_roots(paths)
    assert set(roots) <= {p.resolve() for p in paths}
    for path in paths:
        assert sum(1 for r in roots if r == path or r in path.parents) == 1
    for r in roots:
        assert not any(o != r and o in r.parents for o in roots), "no root is nested in another"


names = st.text(st.sampled_from("abcXYZ019-_."), min_size=1, max_size=12).filter(
    lambda s: s not in {".", ".."} and not s.endswith(".git")
)


@given(
    names,
    names,
    st.sampled_from(
        ["{o}/{n}", "https://github.com/{o}/{n}", "https://github.com/{o}/{n}.git", "git@github.com:x/{o}/{n}/"]
    ),
)
def test_owner_repo_from_slugs_and_urls(owner: str, name: str, form: str) -> None:
    assert owner_repo(form.format(o=owner, n=name)) == f"{owner}/{name}"


BASH = shutil.which("bash")


@pytest.mark.skipif(BASH is None, reason="needs bash")
@settings(max_examples=40, deadline=None)
@given(st.text(st.characters(blacklist_characters="\x00", blacklist_categories=("Cs",)), max_size=40))
def test_launcher_quoting_survives_bash(value: str) -> None:
    assert BASH is not None
    out = subprocess.run([BASH, "-c", f"printf %s {_quote(value)}"], capture_output=True, check=True)
    assert out.stdout.decode("utf-8", "surrogateescape") == value


plugin_ids = st.text(st.sampled_from("abcxyz019_"), min_size=1, max_size=10)
versions = st.text(st.sampled_from("0123456789."), min_size=1, max_size=8)


@given(st.lists(st.tuples(plugin_ids, versions), min_size=2, max_size=6, unique=True))
def test_plugin_zip_names_of_distinct_plugins_differ(plugins: list[tuple[str, str]]) -> None:
    urls = [f"https://plugins.qgis.org/plugins/{p}/version/{v}/download/" for p, v in plugins]
    assert len({plugin_zip_name(url) for url in urls}) == len(urls)


@given(st.lists(st.text(st.sampled_from("abc/-_.z9"), min_size=1, max_size=20), min_size=2, max_size=6, unique=True))
def test_plugin_zip_names_of_distinct_urls_differ(paths: list[str]) -> None:
    urls = {f"https://example.com/{p}".rstrip("/") for p in paths}
    assert len({plugin_zip_name(url) for url in urls}) == len(urls)


@settings(max_examples=60, deadline=None)
@given(
    count=st.integers(min_value=0, max_value=8),
    keep=st.integers(min_value=1, max_value=5),
    protected=st.sets(st.integers(min_value=0, max_value=8), max_size=3),
)
def test_trim_keeps_at_most_keep_sets_and_every_protected_one(
    tmp_path_factory: pytest.TempPathFactory, count: int, keep: int, protected: set[int]
) -> None:
    root = tmp_path_factory.mktemp("cache")
    cache = Cache(Paths(home=root / "home", cache=root / "cache"))
    for i in range(count):
        cache.touch(f"qfieldcloud/images/{i}", root, images=[f"qft-qfieldcloud-app:{i}"])
    protect = {f"qfieldcloud/images/{i}" for i in protected}
    cache.trim("qfieldcloud/images/", keep=keep, protect=protect)
    left = {key for key in cache.load().entries if key.startswith("qfieldcloud/images/")}
    assert protect & {f"qfieldcloud/images/{i}" for i in range(count)} <= left
    assert len(left) <= max(keep, len(protect & left))
